<?php
require __DIR__.'/native_assigned_custom_fields.php';
require_once APPPATH.'services/NativeCompanySettingsForms.php';
$forms=new NativeCompanySettingsForms($db,$p);$store=new CompanySettingsStorage($db,$p);$start=$GLOBALS['essentialChecks'];
$beforeB=$forms->page($b,7,'company');$before=$forms->page($a,7,'company');
$profile=['invoice_company_name'=>'Native settings A','company_info_format'=>'{company_name}<br>{city}'];
$result=$forms->save($a,7,'company',$profile,[],$before['revision']);
essentialCheck($result['values']['invoice_company_name']==='Native settings A'&&$result['values']['company_info_format']===$profile['company_info_format'],'same native identity/format update committed');
essentialCheck($forms->page($b,7,'company')===$beforeB,'company B unchanged');
essentialThrows(fn()=>$forms->save($a,7,'company',['invoice_company_name'=>'stale'],[],$before['revision']),'native_settings_stale','stale form cannot overwrite newer identity');
essentialThrows(fn()=>$forms->save($a,51,'company',$profile,[],$result['revision']),'native_settings_denied','assigned customer grant does not grant company settings');
essentialThrows(fn()=>$forms->save($a,7,'company',['smtp_password'=>'injected'],[],$result['revision']),'native_settings_invalid','company tab cannot write credential');
$locale=['dateformat'=>'Y-m-d|%Y-%m-%d','time_format'=>'24','default_timezone'=>'America/Sao_Paulo','active_language'=>'portuguese_br','enabled_languages'=>['portuguese_br'],'disable_language'=>'1','localization_settings'=>'true'];
$rev=$forms->page($a,7,'localization')['revision'];$tz=date_default_timezone_get();$forms->save($a,7,'localization',$locale,[],$rev);
essentialCheck($store->get($a,'default_timezone')==='America/Sao_Paulo'&&$store->get($b,'default_timezone')===''&&date_default_timezone_get()===$tz,'localization persists only own timezone without process-global mutation');
essentialCheck($store->get($a,'enabled_languages')===serialize(['portuguese_br'])&&!$store->exists($a,'localization_settings'),'native language wire retained, UI marker not stored');
$rev=$forms->page($a,7,'localization')['revision'];$bad=$locale;$bad['default_timezone']='../bad';
essentialThrows(fn()=>$forms->save($a,7,'localization',$bad,[],$rev),'native_settings_invalid','invalid timezone rejected before write');
$def=NativeCompanyCustomFields::definition(['fieldto'=>'company','name'=>'Required company field','type'=>'input','required'=>1]);
$db->query("INSERT INTO {$p}company_custom_fields(issuer_id,fieldto,slug,definition_json,revision) VALUES(?,?,?,?,1)",[$a,'company','company_required',json_encode($def)]);
$before=$forms->page($a,7,'company');
essentialThrows(fn()=>$forms->save($a,7,'company',['invoice_company_name'=>'Must roll back'],[],$before['revision']),'native_custom_field_required','required custom field failure rolls back preceding identity write');
essentialCheck($forms->page($a,7,'company')===$before,'entire native form atomic after custom-field failure');
echo 'Native Settings existing company/localization forms: '.($GLOBALS['essentialChecks']-$start).' checks passed; route admission and remaining sections are separate gates.'.PHP_EOL;
$general=$forms->page($a,7,'general');$generalB=$forms->page($b,7,'general');
$im=imagecreatetruecolor(2,2);ob_start();imagepng($im);$png=ob_get_clean();unset($im);
$input=['companyname'=>'Same native brand','main_domain'=>'https://example.invalid/','rtl_support_admin'=>'0','rtl_support_client'=>'0','allowed_files'=>'.png,.pdf'];
$result=$forms->save($a,7,'general',$input,[],$general['revision'],['logo'=>$png,'logo_dark'=>$png,'favicon'=>$png]);
essentialCheck(count($result['assets']['assets'])===3&&$result['values']['companyname']===$input['companyname'],'same general form commits own logos/favicon and identity atomically');
essentialCheck($forms->page($b,7,'general')===$generalB,'general form never inherits or mutates company B branding');
$bad=$input;$bad['companyname']='Must roll back';
essentialThrows(fn()=>$forms->save($a,7,'general',$bad,[],$result['revision'],['logo'=>'not an image']),'company_asset_invalid_image','invalid image aborts whole native multipart form');
essentialCheck($forms->page($a,7,'general')===$result,'invalid image rolls back preceding settings/identity');
$bad=$input;$bad['main_domain']='javascript:alert(1)';
essentialThrows(fn()=>$forms->save($a,7,'general',$bad,[],$result['revision']),'native_settings_invalid','unsafe native domain rejected');
echo "Native Settings general form images and rollback passed.\n";
